/// <summary>
/// Data contract class for fetching messages
/// </summary>
[DataContract]
class OMGInboundMessageFetchContract
{
    str         packedQuery;

}

Method.Source:
/// <summary>
/// Sets or gets a packed query object
/// </summary>
/// <param name = "_packedQuery">The packed query to set</param>
/// <returns>The packed query</returns>
[DataMemberAttribute, AifQueryTypeAttribute('_packedQuery', querystr(OMGMessageTypeTableQuery))]
public str parmQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;
    return packedQuery;
}

/// <summary>
/// Instantiates a query object from the packed query
/// </summary>
/// <returns>A query object</returns>
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}

/// <summary>
/// Packs the query object
/// </summary>
/// <param name = "_query">The query to pack</param>
public void setQuery(Query _query)
{
    packedQuery = SysOperationHelper::base64Encode(_query.pack());
}
